import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../../core/providers/app_providers.dart';
class QuietHoursScreen extends ConsumerStatefulWidget{const QuietHoursScreen({super.key});@override ConsumerState<QuietHoursScreen> createState()=>_QuietHoursScreenState();}
class _QuietHoursScreenState extends ConsumerState<QuietHoursScreen>{bool enabled=false;String start='22:00',end='07:00';bool loaded=false;@override void didChangeDependencies(){super.didChangeDependencies();if(!loaded){final c=ref.read(appControllerProvider);enabled=c.quietHoursEnabled;start=c.quietStart;end=c.quietEnd;loaded=true;}}
Future<void> pick(bool isStart)async{final current=(isStart?start:end).split(':').map(int.parse).toList();final result=await showTimePicker(context:context,initialTime:TimeOfDay(hour:current[0],minute:current[1]));if(result!=null)setState((){final value='${result.hour.toString().padLeft(2,'0')}:${result.minute.toString().padLeft(2,'0')}';if(isStart)start=value;else end=value;});}
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Quiet hours')),body:ListView(padding:const EdgeInsets.all(20),children:[SwitchListTile(contentPadding:EdgeInsets.zero,title:const Text('Pause reminder alerts during quiet hours'),subtitle:const Text('In-app tasks remain visible. Only notification delivery is deferred.'),value:enabled,onChanged:(v)=>setState(()=>enabled=v)),Card(child:Column(children:[ListTile(title:const Text('Quiet hours start'),subtitle:Text(start),trailing:const Icon(Icons.schedule),onTap:()=>pick(true)),ListTile(title:const Text('Quiet hours end'),subtitle:Text(end),trailing:const Icon(Icons.wb_sunny_outlined),onTap:()=>pick(false))])),const SizedBox(height:12),const Text('Times use your device’s local timezone. Notifications may still be delayed by Android battery controls or system notification settings.'),const SizedBox(height:20),FilledButton(onPressed:start==end?null:()async{await ref.read(appControllerProvider).saveQuietHours(enabled:enabled,start:start,end:end);if(mounted)Navigator.pop(context);},child:const Text('Save quiet hours'))]));}
